//! 📐️ Writes each CAD entity variant, layer, block and exact geometric scalar under ownership control.
use super::{SemioCadSnapshot,CadEntity,CadEntityRecord,CadLayer,CadBlock,SemioPoint2};
use crate::standards::v1::subsets::base::schema::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(super) fn encode(snapshot:&SemioCadSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{native_encoding::encode(encoding,"semio stdio.semio.cad.dsl v1\n","stdio.semio.cad.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn point(value:&SemioPoint2,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.number(value.x,encoding)?;writer.delimiter(b",",encoding)?;writer.number(value.y,encoding)?;writer.delimiter(b"]",encoding)}
fn boolean(value:bool,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.byte(if encoding==SnapshotEncoding::Binary{u8::from(value)}else{if value{b'1'}else{b'0'}})}
fn entity(value:&CadEntity,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{
 writer.entities(1)?;let(binary,text)=match value{CadEntity::Line{..}=>(0,b'L'),CadEntity::Arc{..}=>(1,b'A'),CadEntity::Circle{..}=>(2,b'C'),CadEntity::Ellipse{..}=>(3,b'E'),CadEntity::Polyline{..}=>(4,b'P'),CadEntity::Text{..}=>(5,b'T'),CadEntity::Insert{..}=>(6,b'I'),CadEntity::Solid{..}=>(7,b'S'),CadEntity::Dimension{..}=>(8,b'D')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;writer.delimiter(b"[",encoding)?;
 match value{
 CadEntity::Line{a,b}=>{point(a,writer,encoding)?;writer.delimiter(b",",encoding)?;point(b,writer,encoding)?;},
 CadEntity::Arc{center,radius,start_angle,end_angle}=>{point(center,writer,encoding)?;for value in [radius,start_angle,end_angle]{writer.delimiter(b",",encoding)?;writer.number(*value,encoding)?;}},
 CadEntity::Circle{center,radius}=>{point(center,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.number(*radius,encoding)?;},
 CadEntity::Ellipse{center,major_axis_end,ratio,start_param,end_param}=>{point(center,writer,encoding)?;writer.delimiter(b",",encoding)?;point(major_axis_end,writer,encoding)?;for value in [ratio,start_param,end_param]{writer.delimiter(b",",encoding)?;writer.number(*value,encoding)?;}},
 CadEntity::Polyline{vertices,closed}=>{writer.list(vertices,encoding,|writer,value|point(value,writer,encoding))?;writer.delimiter(b",",encoding)?;boolean(*closed,writer,encoding)?;},
 CadEntity::Text{position,height,rotation,content}=>{point(position,writer,encoding)?;for value in [height,rotation]{writer.delimiter(b",",encoding)?;writer.number(*value,encoding)?;}writer.delimiter(b",",encoding)?;writer.string(content,encoding)?;},
 CadEntity::Insert{block_name,insertion_point,scale,rotation}=>{writer.string(block_name,encoding)?;writer.delimiter(b",",encoding)?;point(insertion_point,writer,encoding)?;writer.delimiter(b",",encoding)?;point(scale,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.number(*rotation,encoding)?;},
 CadEntity::Solid{p1,p2,p3,p4}=>{for(index,value)in [p1,p2,p3,p4].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}point(value,writer,encoding)?;}},
 CadEntity::Dimension{def_point,text_position,measurement,text}=>{point(def_point,writer,encoding)?;writer.delimiter(b",",encoding)?;point(text_position,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.number(*measurement,encoding)?;writer.delimiter(b",",encoding)?;writer.string(text,encoding)?;}
 }writer.delimiter(b"]",encoding)
}
fn record(value:&CadEntityRecord,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.string(&value.handle,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.layer,encoding)?;writer.delimiter(b",",encoding)?;entity(&value.entity,writer,encoding)?;writer.delimiter(b"]",encoding)}
fn layer(value:&CadLayer,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;if encoding==SnapshotEncoding::Binary{writer.varint(value.color_index as u64)?;}else{writer.signed64(i64::from(value.color_index),encoding)?;}writer.delimiter(b",",encoding)?;writer.string(&value.line_type,encoding)?;writer.delimiter(b",",encoding)?;boolean(value.visible,writer,encoding)?;writer.delimiter(b"]",encoding)}
fn block(value:&CadBlock,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;point(&value.base_point,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.entities,encoding,|writer,value|record(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioCadSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nlayers=",encoding)?;writer.list(&snapshot.layers,encoding,|writer,value|layer(value,writer,encoding))?;writer.delimiter(b"\nblocks=",encoding)?;writer.list(&snapshot.blocks,encoding,|writer,value|block(value,writer,encoding))?;writer.delimiter(b"\nentities=",encoding)?;writer.list(&snapshot.entities,encoding,|writer,value|record(value,writer,encoding))}
